const itemJson = ($input.item && $input.item.json) ? $input.item.json : {};
const html = itemJson.body || "";
const channelUsername = "MAKS23";
const results = [];
if (!html) return results;

const wraps = html.split('<div class="tgme_widget_message_wrap');
for (let i = 1; i < wraps.length; i++) {
  const wrap = wraps[i];
  const postMatch = /data-post="([^"]+)"/.exec(wrap);
  if (!postMatch) continue;
  const postPath = postMatch[1];

  const textMatch = /<div class="tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/.exec(wrap);
  const rawText = textMatch ? textMatch[1] : "";
  const cleanText = rawText.replace(/<[^>]+>/g, '').trim();
  if (!cleanText) continue;

  const timeMatch = /<time[^>]*datetime="([^"]+)"/.exec(wrap);
  const isoDate = timeMatch ? timeMatch[1] : new Date().toISOString();

  const lines = cleanText.split('\n').map(l => l.trim()).filter(Boolean);
  const title = lines[0] ? lines[0].substring(0, 200) : "Telegram Channel Update";

  results.push({
    json: {
      title: `[@${channelUsername}] ${title}`,
      description: cleanText,
      source_name: `Telegram Channel (@${channelUsername})`,
      source_url: `https://t.me/${postPath}`,
      is_darknet: false,
      date_reported: isoDate
    }
  });
}

return results.slice(-10);
